mapper.select:
SELECT id, userName, pWord, identity, head, createTime, state from user


userName like concat('%',#{userName},'%')


and state = #{state}


and identity = #{identity}


and createTime >= #{startTime}


and createTime <= #{endTime}


order by createTime asc

SELECT dl.id, u.userName, dl.down_reason, dl.down_time, dl.down_end, dl.down_end_time, ua.userName AS down_admin_name, uae.userName AS down_end_admin_name FROM down_log dl LEFT JOIN user u ON u.id = dl.user_id LEFT JOIN user ua ON ua.id = dl.down_admin_id LEFT JOIN user uae ON uae.id = dl.down_end_admin_id
u.userName LIKE CONCAT('%', #{userName}, '%')
AND dl.down_end = #{downEnd}
AND dl.down_time >= #{downTimeStart}
AND dl.down_time <= #{downTimeEnd}
ORDER BY dl.down_time DESC

select uiul.id, u.userName as user_name, uiul.old_identity, uiul.new_identity, uiul.update_reason, uiul.update_time, u1.userName as update_admin_name from user_identity_update_log uiul left join user u on uiul.user_id = u.id left join user u1 on uiul.update_admin_id = u1.id
u.userName LIKE CONCAT('%', #{userName}, '%')
AND uiul.old_identity = #{oldIdentity}
AND uiul.new_identity = #{newIdentity}
AND uiul.update_time >= #{downTimeStart}
AND uiul.update_time <= #{downTimeEnd}
